// Province → district → sub-district (+ zip) data for the address form's
// cascading selects. Served from public/data/thai-geo.json (generated by
// scripts/gen_thai_geo.mjs) so it stays out of the JS bundle and is only
// fetched when an address form opens.
export type ThaiGeo = Record<string, Record<string, [subDistrict: string, zip: string][]>>

let geoPromise: Promise<ThaiGeo> | null = null

/** Fetch once per page load; a failed fetch is not cached so it can retry. */
export function loadThaiGeo(): Promise<ThaiGeo> {
  if (!geoPromise) {
    geoPromise = fetch("/data/thai-geo.json")
      .then((r) => {
        if (!r.ok) throw new Error(`thai-geo ${r.status}`)
        return r.json() as Promise<ThaiGeo>
      })
      .catch((e) => {
        geoPromise = null
        throw e
      })
  }
  return geoPromise
}

export const districtsOf = (geo: ThaiGeo, province: string): string[] =>
  Object.keys(geo[province] ?? {})

export const subDistrictsOf = (geo: ThaiGeo, province: string, district: string) =>
  geo[province]?.[district] ?? []
